fn largest_divisor(n: i8) -> i8 {
    // Since n > 1, we start checking from n/2 down to 2
    // The largest proper divisor cannot exceed n/2
    let half = n / 2;
    
    for d in (2..=half).rev() {
        if n % d == 0 {
            return d;
        }
    }
    
    // If no divisor found in the range, then n is prime
    // The largest proper divisor of a prime number is 1
    1
}